export function Breakpoint({
  width = {{width}},
  breakpointValue = {{breakpointValue}},
  label = "{{label}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 660 }}>
      <div style={{ fontSize: 11, color: "#241430aa", marginBottom: 8 }}>{label} &mdash; {width}px wide, breakpoint at {breakpointValue}px</div>
      <div style={{ width, maxWidth: "100%", containerType: "inline-size", background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, padding: 14, boxSizing: "border-box" }}>
        <div className="layout" style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          <div style={{ flex: 1, padding: 14, borderRadius: 8, color: "#241430", fontWeight: 700, textAlign: "center", background: accent }}>A</div>
          <div style={{ flex: 1, padding: 14, borderRadius: 8, color: "#241430", fontWeight: 700, textAlign: "center", background: accent }}>B</div>
        </div>
        <p className="state" style={{ fontSize: 12, color: "#241430aa", marginTop: 8 }} />
      </div>
      <style>{`
        .state::before { content: "Stacked (below breakpoint)"; }
        @container (min-width: ${breakpointValue}px) {
          .layout { flex-direction: row; }
          .state::before { content: "Side by side (breakpoint reached)"; }
        }
      `}</style>
    </div>
  );
}
